package dev.eugheist.tc4modern;
import java.util.*;
import net.minecraft.core.*;
import net.minecraft.core.registries.*;
import net.minecraft.server.level.ServerPlayer;
import net.minecraft.world.*;
import net.minecraft.world.entity.*;
import net.minecraft.world.entity.ai.attributes.Attributes;
import net.minecraft.world.entity.projectile.AbstractArrow;
import net.minecraft.world.entity.item.ItemEntity;
import net.minecraft.world.item.*;
import net.minecraft.world.item.enchantment.*;
import net.minecraft.world.effect.*;
import net.minecraft.world.level.block.Blocks;
import net.minecraft.world.phys.*;
import net.neoforged.bus.api.SubscribeEvent;
import net.neoforged.fml.common.EventBusSubscriber;
import thaumcraft.api.aspects.*;
@EventBusSubscriber(modid=TC4Modern.MODID,value=net.neoforged.api.distmarker.Dist.CLIENT)
final class PrimalArrowAudit {
 static int ticks;static volatile boolean prepared,finished;static final BlockPos POS=InfusionAudit.POS;static final List<PrimalArrows.ArrowEntity> displayed=new ArrayList<>();static PrimalArrows.ArrowEntity wallArrow;static ItemStack automaticBow;
 static void check(boolean b,String s){if(!b)throw new IllegalStateException("TC4_BOW FAIL "+s);System.out.println("TC4_BOW PASS "+s);}
 static AbstractArrow shoot(ServerPlayer p,ItemStack bow,int charge){var l=p.serverLevel();var before=l.getEntitiesOfClass(AbstractArrow.class,new AABB(POS).inflate(30)).stream().map(Entity::getId).collect(java.util.stream.Collectors.toSet());p.setItemInHand(InteractionHand.MAIN_HAND,bow);check(bow.use(p.level(),p,InteractionHand.MAIN_HAND).getResult().consumesAction(),"actual bow nock");bow.getItem().releaseUsing(bow,l,p,72000-charge);p.stopUsingItem();return l.getEntitiesOfClass(AbstractArrow.class,new AABB(POS).inflate(30)).stream().filter(a->!before.contains(a.getId())).findFirst().orElseThrow();}
 static void enchant(ServerPlayer p,ItemStack bow,net.minecraft.resources.ResourceKey<Enchantment> key,int value){bow.enchant(p.registryAccess().lookupOrThrow(Registries.ENCHANTMENT).getOrThrow(key),value);}
 static void prepare(ServerPlayer p){InfusionAudit.prepare(p);InfusionAudit.matrix.logic.crafting=false;var l=p.serverLevel();l.getEntitiesOfClass(ItemEntity.class,new AABB(POS).inflate(25)).forEach(Entity::discard);p.getInventory().clearContent();p.getInventory().selected=0;for(var slot:EquipmentSlot.values())if(slot.isArmor())p.setItemSlot(slot,ItemStack.EMPTY);l.setDayTime(6000);l.setWeatherParameters(10000,0,false,false);p.connection.teleport(POS.getX()+7,POS.getY()+2,POS.getZ()-8,0,0);
  for(var r:ArcaneRecipes.entries().stream().filter(x->x.key().equals("BoneBow")||x.key().startsWith("PrimalArrow_")).toList()){var grid=r.ingredients().stream().map(i->i.isEmpty()?ItemStack.EMPTY:i.getItems()[0].copy()).toList();check(r.matches(grid,Set.of(r.research()))&&!r.matches(grid,Set.of()),"real arcane recipe and research "+r.key());var wand=WandParts.make(WandParts.CAPS.get("gold"),WandParts.RODDEFS.get("greatwood"));for(var aspect:Aspect.getPrimalAspects())WandData.add(wand,aspect,50,true);var expectedWand=wand.copy();WandData.consumeCrafting(expectedWand,r.cost(),true,p);var table=new SimpleContainer(10);for(int i=0;i<9;i++)table.setItem(i,grid.get(i));table.setItem(9,wand);var menu=new ArcaneWorkbenchMenu(0,p.getInventory(),net.minecraft.world.inventory.ContainerLevelAccess.NULL,table);check(menu.slots.get(0).mayPickup(p)&&ItemStack.isSameItemSameComponents(menu.slots.get(0).getItem(),r.output()),"actual workbench result "+r.key());var made=menu.slots.get(0).remove(r.output().getCount());menu.slots.get(0).onTake(p,made);check(made.getCount()==r.output().getCount()&&ItemStack.isSameItemSameComponents(wand,expectedWand)&&java.util.stream.IntStream.range(0,9).allMatch(i->table.getItem(i).isEmpty()),"actual craft consumes all ingredients and exact discounted vis "+r.key());menu.removed(p);if(r.key().startsWith("PrimalArrow_"))check(r.output().getCount()==8&&r.cost().visSize()==8,"8arrows from8ordinary+shard8vis "+r.key());}
  var bow=new ItemStack(PrimalArrows.bow());check(bow.getMaxDamage()==512&&bow.getEnchantmentValue()==3,"original512durability3enchantability");p.getInventory().setItem(1,new ItemStack(Items.ARROW,3));var ordinary=shoot(p,bow,10);check(!(ordinary instanceof PrimalArrows.ArrowEntity)&&Math.abs(ordinary.getDeltaMovement().length()-3.75)<.12&&ordinary.getBaseDamage()==2.5&&!ordinary.isCritArrow()&&bow.getDamageValue()==1&&p.getInventory().getItem(1).getCount()==2,"bone bow10tick full3.75speed2.5damage noCrit consumes ordinary+durability");ordinary.discard();var punchBow=new ItemStack(PrimalArrows.bow());enchant(p,punchBow,Enchantments.PUNCH,2);var punchArrow=shoot(p,punchBow,10);var punched=EntityType.HUSK.create(l);punched.setNoAi(true);punched.getAttribute(Attributes.KNOCKBACK_RESISTANCE).setBaseValue(1);punched.moveTo(POS.getX()+10.5,POS.getY()-2,POS.getZ()+5.5,0,0);l.addFreshEntity(punched);punchArrow.setPos(punched.getX(),punched.getY()+.9,punched.getZ()-1.5);punchArrow.setDeltaMovement(0,0,3.75);punchArrow.tick();check(punchArrow.isRemoved()&&Math.abs(punched.getDeltaMovement().z-1.2)<.0001,"actual bone PunchII collision uses original1.2 knockback ignoring resistance");punched.discard();
  for(int type=0;type<6;type++){p.getInventory().setItem(1,new ItemStack(Items.ARROW,3));p.getInventory().setItem(2,new ItemStack(PrimalArrows.arrow(type),3));var shot=(PrimalArrows.ArrowEntity)shoot(p,new ItemStack(Items.BOW),20);check(shot.type()==type&&shot.isCritArrow()&&shot.pickup==AbstractArrow.Pickup.DISALLOWED&&p.getInventory().getItem(1).getCount()==3&&p.getInventory().getItem(2).getCount()==2,"primal"+type+" priority over ordinary,20tick vanillaCrit,noPickup,consumed");double expected=type==3?3:type==4||type==5?1.6:2;check(Math.abs(shot.getBaseDamage()-expected)<.0001&&shot.knockback==(type==3?1:0),"original elemental damage/punch "+type);shot.discard();
   var hit=new PrimalArrows.ArrowEntity(PrimalArrows.ENTITY.get(),l);hit.getEntityData().set(PrimalArrows.ArrowEntity.TYPE,type);hit.setOwner(p);hit.setDeltaMovement(0,0,3);var victim=EntityType.HUSK.create(l);victim.setNoAi(true);victim.getAttribute(Attributes.ARMOR).setBaseValue(0);victim.getAttribute(Attributes.MAX_HEALTH).setBaseValue(200);victim.setHealth(200);victim.moveTo(POS.getX()+type*2-6,POS.getY()-2,POS.getZ()+7,180,0);if(type==0||type==4){victim.getAttribute(Attributes.ARMOR).setBaseValue(20);victim.addEffect(new MobEffectInstance(MobEffects.DAMAGE_RESISTANCE,600,4));}l.addFreshEntity(victim);hit.onHitEntity(new EntityHitResult(victim));check(Math.abs(victim.getHealth()-(200-Math.ceil(3*expected)))<.001,"native hit exact damage incl armor/resistance bypass "+type);if(type==1)check(victim.getRemainingFireTicks()==100,"fire arrow burns5seconds");if(type==2)check(victim.getEffect(MobEffects.MOVEMENT_SLOWDOWN).getAmplifier()==4&&victim.getEffect(MobEffects.MOVEMENT_SLOWDOWN).getDuration()==200,"water SlownessV10seconds");if(type==4)check(victim.getEffect(MobEffects.WEAKNESS).getAmplifier()==4&&victim.getEffect(MobEffects.WEAKNESS).getDuration()==200,"order WeaknessV10seconds");if(type==5)check(victim.getEffect(MobEffects.WITHER).getDuration()==100,"entropy WitherI5seconds");victim.discard();
   var display=new PrimalArrows.ArrowEntity(PrimalArrows.ENTITY.get(),l);display.getEntityData().set(PrimalArrows.ArrowEntity.TYPE,type);display.setPos(POS.getX()+type*1.3-4,POS.getY(),POS.getZ()-3);display.setNoGravity(true);l.addFreshEntity(display);displayed.add(display);var saved=display.saveWithoutId(new net.minecraft.nbt.CompoundTag());var copy=new PrimalArrows.ArrowEntity(PrimalArrows.ENTITY.get(),l);copy.load(saved);check(copy.type()==type&&copy.pickup==AbstractArrow.Pickup.DISALLOWED,"type spawn/NBT persistence "+type);
  }
  p.getInventory().setItem(2,new ItemStack(PrimalArrows.arrow(3),3));var earthBow=new ItemStack(PrimalArrows.bow());enchant(p,earthBow,Enchantments.POWER,1);var earth=(PrimalArrows.ArrowEntity)shoot(p,earthBow,10);check(Math.abs(earth.getBaseDamage()-9.375)<.0001&&!earth.isCritArrow(),"original repeated earth multiplier bone+PowerI gives9.375base");earth.discard();var infinity=new ItemStack(Items.BOW);enchant(p,infinity,Enchantments.INFINITY,1);p.getInventory().setItem(2,new ItemStack(PrimalArrows.arrow(0),2));var inf=shoot(p,infinity,20);check(p.getInventory().getItem(2).getCount()==1,"original Infinity bug still consumes in survival");inf.discard();p.setGameMode(net.minecraft.world.level.GameType.CREATIVE);p.getInventory().setItem(2,new ItemStack(PrimalArrows.arrow(0),2));var creative=shoot(p,new ItemStack(Items.BOW),20);check(p.getInventory().getItem(2).getCount()==1,"original creative without Infinity still consumes primal");creative.discard();p.setGameMode(net.minecraft.world.level.GameType.SURVIVAL);p.getAbilities().mayfly=true;p.getAbilities().flying=true;p.onUpdateAbilities();p.getInventory().setItem(2,ItemStack.EMPTY);
  wallArrow=new PrimalArrows.ArrowEntity(PrimalArrows.ENTITY.get(),l);wallArrow.setPos(POS.getX()+9.5,POS.getY(),POS.getZ()-3.5);wallArrow.shoot(0,0,1,1,0);l.setBlock(POS.offset(9,0,0),Blocks.STONE.defaultBlockState(),3);l.addFreshEntity(wallArrow);automaticBow=new ItemStack(PrimalArrows.bow());p.getInventory().setItem(1,new ItemStack(Items.ARROW,2));p.setItemInHand(InteractionHand.MAIN_HAND,automaticBow);automaticBow.use(l,p,InteractionHand.MAIN_HAND);p.connection.teleport(POS.getX()+5,POS.getY()+2,POS.getZ()-10,45,22);prepared=true;
 }
 static void finish(ServerPlayer p){check(wallArrow.isRemoved(),"actual block collision despawns primal arrow after100groundticks");check(automaticBow.getDamageValue()==1&&!p.isUsingItem()&&p.getInventory().getItem(1).getCount()==1,"actual player ticks autorelease bone bow after18ticks");finished=true;}
 @SubscribeEvent static void tick(net.neoforged.neoforge.client.event.ClientTickEvent.Post e){if(!Boolean.getBoolean("tc4modern.bowAuditOnly"))return;var mc=net.minecraft.client.Minecraft.getInstance();if(mc.player==null||mc.level==null)return;ticks++;var server=mc.getSingleplayerServer();var id=mc.player.getUUID();if(ticks==80)server.execute(()->prepare(server.getPlayerList().getPlayer(id)));if(ticks==120){check(prepared&&PrimalArrowsClient.rendered>0,"six native colored arrow renderers");LiquidDeathAudit.shot(mc,"primal-arrows-world.png");}if(ticks==240)server.execute(()->finish(server.getPlayerList().getPlayer(id)));if(ticks>=260&&(ticks-260)%20==0){check(finished,"server projectile mechanics complete");int i=(ticks-260)/20;if(i>=3){mc.stop();return;}var inv=mc.player.getInventory();var book=new ThaumonomiconScreen(new ThaumonomiconMenu(0,inv),inv,net.minecraft.network.chat.Component.empty());book.auditOpen(thaumcraft.api.research.ResearchCategories.getResearch(i==0?"BONEBOW":"PRIMALARROW"),i==2?2:0);mc.setScreen(book);}if(ticks>=265&&(ticks-265)%20==0)LiquidDeathAudit.shot(mc,"primal-arrow-book-"+(ticks-265)/20+".png");}
}
